def transform(grid):
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0])
    reach=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in range(w):
            if (i==0 or i==h-1 or j==0 or j==w-1) and g[i][j]==0:
                reach[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not reach[ni][nj] and g[ni][nj]==0:
                reach[ni][nj]=True; dq.append((ni,nj))
